56	/**
57	 * Gestione asset di un singolo record (digital-hub #16).
58	 *
59	 * Page record-scoped, full-width, fuori dalla navigazione: si raggiunge solo
60	 * dall'azione {@see \AtrioTeam\DigitalHub\Assets\Filament\Actions\ManageAssetsAction}
61	 * nella tabella di una resource. La route porta owner via coppia polimorfica
62	 * (morph alias + chiave): `/assets/{ownerType}/{owner}`, così la pagina è
63	 * generica per qualunque modello che usa il trait HasAssets, non solo Product.
64	 *
65	 * Lo stato dell'UI (folder attiva, ecc.) sarà aggiunto negli step successivi
66	 * di #16a; qui c'è solo lo scheletro navigabile.
67	 */
68	class AssetManager extends Page implements HasActions
69	{
70	    use InteractsWithActions;
71	
72	    protected static string|BackedEnum|null $navigationIcon = Heroicon::OutlinedFolderOpen;
73	
74	    protected static ?string $slug = 'assets';
75	
76	    protected string $view = 'digital-hub::filament.pages.asset-manager';
77	
78	    protected Width|string|null $maxContentWidth = Width::Full;
79	
80	    /**
81	     * Layout "base" (solo body, niente sidebar/topbar): la pagina è un editor di
82	     * asset a tutto schermo, presentato come un "finto modal" che si chiude con la
83	     * X tornando al catalogo (vedi blade). Il layout base include comunque gli
84	     * stili/script Filament e il componente notifiche, quindi toast e modali delle
85	     * action continuano a funzionare.
86	     */
87	    protected static string $layout = 'filament-panels::components.layout.base';
88	
89	    /** icona di "sposta", usata per file e cartelle */
90	    protected Heroicon $moveActionIcon = Heroicon::OutlinedArrowUpOnSquareStack;
91	
92	    /** Morph alias del record proprietario (es. `product`). */
93	    public string $ownerType;
94	
95	    /** Chiave primaria del record proprietario. */
96	    public int|string $ownerKey;
97	
98	    /** Folder attualmente selezionata; null = root ("Home") del record. */
99	    public ?int $activeFolderId = null;
100	
101	    /**
102	     * URL della lista da cui si è arrivati (catturato dal Referer alla mount),
103	     * per il link "indietro". null se assente o non locale. È public così
104	     * sopravvive alle update Livewire successive (la mount gira una sola volta).
105	     */
106	    public ?string $returnUrl = null;
107	
108	    /**
109	     * Id dei media selezionati per le azioni multiple (checkbox sulle card).
110	     * @var array<int, int|string>
111	     */
112	    public array $selectedAssetIds = [];
113	
114	    /**
115	     * Id delle sottocartelle selezionate per le azioni multiple (checkbox sulle
116	     * tile cartella). Una cartella selezionata vale come "tutti i media del suo
117	     * sottoalbero" per scarica/condividi; sposta/elimina multipli restano
118	     * solo-file (nascosti quando ci sono cartelle in selezione).
119	     * @var array<int, int|string>
120	     */
121	    public array $selectedFolderIds = [];
122	
123	    /** URL dell'ultimo share creato, mostrato nel modal "share-link" (22g). */
124	    public ?string $lastShareUrl = null;
125	
126	    /**
127	     * Cache per-request del record risolto (privata: non serializzata da Livewire).
128	     * @var (Model&OwnsAssets)|null
129	     */
130	    private ?Model $ownerModel = null;
131	
132	    /**
133	     * Cache per-request delle folder del record (privata: non serializzata da Livewire).
134	     * @var null|EloquentCollection<int,AssetFolder>
135	     */
136	    private ?EloquentCollection $folderCache = null;
137	
138	    /**
139	     * Cache per-request del resolver ownership-scoped (privata: non serializzata
140	     * da Livewire).
141	     */
142	    private ?OwnedAssetResolver $resolverCache = null;
143	
144	    /**
145	     * Cache del builder delle preview delle tile cartella (miniature,
146	     * conteggi, stato), privata: non serializzata da Livewire.
147	     */
148	    private ?SubfolderPreviewBuilder $subfolderPreviewCache = null;
149	
150	    #[Override]
151	    public static function getRoutePath(Panel $panel): string
152	    {
153	        return '/assets/{ownerType}/{owner}';
154	    }
155	
156	    public static function shouldRegisterNavigation(): bool
157	    {
158	        return false;
159	    }
160	
161	    /**
162	     * I parametri di route (ownerType, owner) sono iniettati da Livewire.
163	     */
164	    public function mount(string $ownerType, int|string $owner): void
165	    {
166	        $this->ownerType = $ownerType;
167	        $this->ownerKey = $owner;
168	
169	        // valida subito: record risolvibile e dotato del trait HasAssets
170	        $this->resolveOwner();
171	
172	        // la lista di provenienza (con i suoi filtri, es. sottocategoria) è
173	        // esattamente la pagina che ha linkato qui: la prendiamo dal Referer.
174	        // Fallback (link diretto/tab nuova, niente referer): la lista della
175	        // resource del record, senza filtri.
176	        $this->returnUrl = $this->resolveReturnUrl(request()->headers->get('referer'))
177	            ?? $this->resourceIndexUrl();
178	    }
179	
180	    /**
181	     * Valida l'URL di ritorno: accetta solo URL dello stesso host dell'app (no
182	     * open redirect verso domini esterni) e scarta l'auto-riferimento alla
183	     * pagina asset stessa (es. reload). null se non valido.
184	     */
185	    private function resolveReturnUrl(?string $url): ?string
186	    {
187	        if (! is_string($url) || $url === '') {
188	            return null;
189	        }
190	
191	        $host = parse_url($url, PHP_URL_HOST);
192	        if ($host !== null && $host !== request()->getHost()) {
193	            return null;
194	        }
195	
196	        // non puntare a sé stessa (la pagina asset): eviterebbe un "indietro" che non torna indietro
197	        if (str_contains((string) parse_url($url, PHP_URL_PATH), '/assets/')) {
198	            return null;
199	        }
200	
201	        return $url;
202	    }
203	
204	    /**
205	     * URL della lista (index) della resource Filament del record, da usare come
206	     * fallback quando manca un Referer valido. null se il record non ha una
207	     * resource registrata nel pannello o l'URL non è risolvibile.
208	     */
209	    private function resourceIndexUrl(): ?string
210	    {
211	        /** @var class-string<\Filament\Resources\Resource>|null $resource */
212	        $resource = \Filament\Facades\Filament::getModelResource($this->resolveOwner());
213	        if ($resource === null) {
214	            return null;
215	        }
216	
217	        try {
218	            $url = $resource::getUrl('index');
219	
220	            return $url ?: null;
221	        } catch (\Throwable) {
222	            return null;
223	        }
224	    }
225	
226	    /**
227	     * Risolve il record proprietario dalla coppia (morph alias, chiave).
228	     * 404 se il tipo non è mappato, il record non esiste o non è OwnsAssets.
229	     *
230	     * @return Model&OwnsAssets
231	     */
232	    public function resolveOwner(): Model
233	    {
234	        if ($this->ownerModel !== null) {
235	            return $this->ownerModel;
236	        }
237	
238	        $class = Relation::getMorphedModel($this->ownerType) ?? $this->ownerType;
239	        abort_unless(class_exists($class), 404);
240	
241	        /** @var class-string<Model> $class */
242	        $record = $class::query()->find($this->ownerKey);
243	        abort_unless($record instanceof OwnsAssets, 404);
244	
245	        return $this->ownerModel = $record;
246	    }
247	
248	    #[Override]
249	    public function getTitle(): string|Htmlable
250	    {
251	        $owner = $this->resolveOwner();
252	        $name = $owner->getAttribute('name');
253	        $key = $owner->getKey();
254	        $label = is_string($name) && $name !== ''
255	            ? $name
256	            : '#' . (is_scalar($key) ? (string) $key : '');
257	
258	        return (string) __('digital-hub::assets.title_for', ['owner' => $label]);
259	    }
260	
261	    /**
262	     * Nessun heading di pagina Filament: il titolo è renderizzato dalla barra del
263	     * finto modal nel blade. Tornando '' (vuoto) il componente di pagina non
264	     * disegna affatto l'header, evitando il doppione.
265	     */
266	    #[Override]
267	    public function getHeading(): string|Htmlable
268	    {
269	        return '';
270	    }
271	
272	    /**
273	     * Tutte le folder del record, caricate una sola volta per request.
274	     *
275	     * @return EloquentCollection<int, AssetFolder>
276	     */
277	    public function allFolders(): EloquentCollection
278	    {
279	        if ($this->folderCache !== null) {
280	            return $this->folderCache;
281	        }
282	
283	        return $this->folderCache = $this->resolveOwner()->allAssetFolders();
284	    }
285	
286	    /**
287	     * Vista ad albero sulle folder del record. Costruita al volo dalla collection
288	     * già cachata per-request ({@see allFolders()}): non tiene stato proprio, così
289	     * l'invalidazione di {@see $folderCache} basta a rifletterne i cambiamenti.
290	     */
291	    private function folderTree(): FolderTree
292	    {
293	        return FolderTree::fromFolders($this->allFolders());
294	    }
295	
296	    /**
297	     * Resolver ownership-scoped per media e folder del record. L'owner non cambia
298	     * nell'arco della request: lo cachiamo una volta (privata, non serializzata
299	     * da Livewire).
300	     */
301	    private function resolver(): OwnedAssetResolver
302	    {
303	        return $this->resolverCache ??= OwnedAssetResolver::for($this->resolveOwner());
304	    }
305	
306	    /**
307	     * Seleziona la folder attiva (null = root). Ignora id non appartenenti al
308	     * record (es. manomissione del payload Livewire).
309	     */
310	    public function selectFolder(?int $folderId): void
311	    {
312	        // cambiando vista la selezione corrente non ha più senso
313	        $this->selectedAssetIds = [];
314	        $this->selectedFolderIds = [];
315	
316	        if ($folderId === null) {
317	            $this->activeFolderId = null;
318	
319	            return;
320	        }
321	
322	        if ($this->allFolders()->firstWhere('id', $folderId) !== null) {
323	            $this->activeFolderId = $folderId;
324	        }
325	    }
326	
327	    /**
328	     * Svuota la selezione corrente (pulsante "Annulla selezione").
329	     */
330	    public function clearAssetSelection(): void
331	    {
332	        $this->selectedAssetIds = [];
333	        $this->selectedFolderIds = [];
334	    }
335	
336	    /**
337	     * Seleziona tutti gli asset e le sottocartelle attualmente visibili nella
338	     * vista corrente (pulsante "Seleziona tutti", disponibile dopo la prima
339	     * selezione).
340	     */
341	    public function selectAllAssets(): void
342	    {
343	        $this->selectedAssetIds = $this->getAssets()
344	            ->map(function (Media $media): string {
345	                $key = $media->getKey();
346	
347	                return is_int($key) || is_string($key) ? (string) $key : '';
348	            })
349	            ->all();
350	
351	        $this->selectedFolderIds = $this->getSubfolders()
352	            ->map(fn (AssetFolder $folder): string => (string) $folder->id)
353	            ->all();
354	    }
355	
356	    /**
357	     * Sposta un media in una folder (o root) via drag-drop sull'albero (#16b).
358	     * `$mediaId` arriva come stringa dal dataTransfer; `$folderId` null = root.
359	     */
360	    public function moveAssetToFolder(mixed $mediaId, ?int $folderId): void
361	    {
362	        $media = $this->findOwnedMedia($mediaId);
363	        if ($media === null) {
364	            return;
365	        }
366	
367	        if ($folderId !== null && $this->findOwnedFolder($folderId) === null) {
368	            $folderId = null;
369	        }
370	
371	        $media->setAttribute('asset_folder_id', $folderId);
372	        $media->save();
373	
374	        Notification::make()->success()->title(__('digital-hub::assets.asset_moved'))->send();
375	    }
376	
377	    /**
378	     * Riordina un gruppo di folder fratelli via drag-drop nell'albero (#16b).
379	     * Riceve gli id nel nuovo ordine (da SortableJS) e riassegna `sort` per
380	     * posizione. Gli id estranei al record sono ignorati.
381	     *
382	     * @param array<int, int|string> $orderedIds
383	     */
384	    public function reorderFolders(array $orderedIds): void
385	    {
386	        foreach (array_values($orderedIds) as $index => $id) {
387	            $folder = $this->findOwnedFolder($id);
388	            if ($folder === null) {
389	                continue;
390	            }
391	
392	            if ($folder->sort !== $index) {
393	                $folder->sort = $index;
394	                $folder->save();
395	            }
396	        }
397	
398	        $this->folderCache = null;
399	    }
400	
401	    /**
402	     * Albero annidato delle folder del record per il pannello sinistro.
403	     * `children` è ricorsivamente la stessa struttura (non esprimibile come tipo
404	     * ricorsivo preciso in PHPDoc, quindi `mixed`).
405	     *
406	     * @return array<int, array{folder: AssetFolder, children: mixed}>
407	     */
408	    public function getFolderTree(): array
409	    {
410	        return $this->folderTree()->nested();
411	    }
412	
413	    /**
414	     * Sottocartelle dirette della folder attiva, da mostrare come tile nel
415	     * pannello destro insieme ai file. In root ("Home") sono le cartelle di
416	     * primo livello: la root si naviga come una cartella qualunque.
417	     *
418	     * @return \Illuminate\Support\Collection<int, AssetFolder>
419	     */
420	    public function getSubfolders(): \Illuminate\Support\Collection
421	    {
422	        return $this->folderTree()->childrenOf($this->activeFolderId);
423	    }
424	
425	    /**
426	     * Catena dalla root alla folder attiva, per il breadcrumb. Vuota se siamo
427	     * in root. Se l'id attivo non esiste più (folder eliminata), resetta a root.
428	     *
429	     * @return list<AssetFolder>
430	     */
431	    public function getBreadcrumbTrail(): array
432	    {
433	        if ($this->activeFolderId === null) {
434	            return [];
435	        }
436	
437	        $trail = $this->folderTree()->breadcrumb($this->activeFolderId);
438	        if ($trail === null) {
439	            // folder eliminata sotto i piedi: torna a root
440	            $this->activeFolderId = null;
441	
442	            return [];
443	        }
444	
445	        return $trail;
446	    }
447	
448	    /**
449	     * Media mostrati nel pannello destro: i soli media diretti della folder
450	     * attiva. In root ("Home") sono i file caricati direttamente in root
451	     * (nessuna folder assegnata), come in una cartella qualunque.
452	     *
453	     * @return \Illuminate\Support\Collection<int, \Spatie\MediaLibrary\MediaCollections\Models\Media>
454	     */
455	    public function getAssets(): \Illuminate\Support\Collection
456	    {
457	        $folder = $this->activeFolderId !== null
458	            ? $this->findOwnedFolder($this->activeFolderId)
459	            : null;
460	
461	        return $this->resolveOwner()->assetsInFolder($folder);
462	    }
463	
464	    // -- Preview delle cartelle (14b) -----------------------------------------
465	
466	    /**
467	     * Builder delle derivate delle tile (miniature, conteggi, stato) sui media
468	     * dei sottoalberi delle sottocartelle visibili. Cachato per-request: dipende
469	     * dalla folder attiva, che non cambia nell'arco della request (privata: non
470	     * serializzata da Livewire).
471	     */
472	    private function subfolderPreview(): SubfolderPreviewBuilder
473	    {
474	        return $this->subfolderPreviewCache ??= SubfolderPreviewBuilder::for(
475	            $this->getSubfolders(),
476	            $this->folderTree(),
477	            $this->resolver(),
478	        );
479	    }
480	
481	    /**
482	     * @return array<int, list<array{url: string, inProgress: bool}>> id sottocartella => miniature
483	     */
484	    public function getSubfolderPreviews(): array
485	    {
486	        return $this->subfolderPreview()->previews();
487	    }
488	
489	    /**
490	     * @return array<int, int> id sottocartella => numero di file nel sottoalbero
491	     */
492	    public function getSubfolderFileCounts(): array
493	    {
494	        return $this->subfolderPreview()->fileCounts();
495	    }
496	
497	    /**
498	     * True se tra i media dei sottoalberi delle sottocartelle visibili ce n'è
499	     * almeno uno in lavorazione: estende il polling della griglia (che guarda
500	     * solo gli asset della folder attiva) così le preview delle tile cartella
501	     * compaiono da sole a job concluso.
502	     */
503	    public function hasProcessingInSubfolders(): bool
504	    {
505	        return $this->subfolderPreview()->hasProcessing();
506	    }
507	
508	    // -- CRUD folder (#16a step 3) ------------------------------------------
509	
510	    /**
511	     * Crea una folder sotto la folder attiva (root se nessuna selezionata).
512	     * Le invarianti (profondità, owner, cicli) sono enforce dal model in saving.
513	     */
514	    public function createFolderAction(): Action
515	    {
516	        return Action::make('createFolder')
517	            ->label(__('digital-hub::assets.new_folder'))
518	            ->icon(Heroicon::OutlinedFolderPlus)
519	            ->modalHeading(fn (): string => $this->activeFolderId === null
520	                ? (string) __('digital-hub::assets.new_folder')
521	                : (string) __('digital-hub::assets.new_subfolder'))
522	            ->schema([
523	                TextInput::make('name')
524	                    ->label(__('digital-hub::assets.folder_name'))
525	                    ->required()
526	                    ->maxLength(255),
527	            ])
528	            ->action(function (array $data): void {
529	                $owner = $this->resolveOwner();
530	                $parent = $this->activeFolderId !== null
531	                    ? $this->findOwnedFolder($this->activeFolderId)
532	                    : null;
533	                $name = is_string($data['name']) ? $data['name'] : '';
534	
535	                try {
536	                    // createAssetFolder salva internamente: il saving hook del
537	                    // model applica le invarianti (profondità, owner, cicli).
538	                    $owner->createAssetFolder($name, $parent);
539	                } catch (ValidationException $e) {
540	                    Notification::make()->danger()->title($this->firstValidationMessage($e))->send();
541	
542	                    return;
543	                }
544	
545	                $this->folderCache = null;
546	                Notification::make()->success()->title(__('digital-hub::assets.folder_created'))->send();
547	            });
548	    }
549	
550	    /**
551	     * Rinomina una folder del record. `folder` (id) passato come argument.
552	     */
553	    public function renameFolderAction(): Action
554	    {
555	        return Action::make('renameFolder')
556	            ->label(__('digital-hub::assets.rename_folder'))
557	            ->icon(Heroicon::OutlinedPencilSquare)
558	            ->iconButton()
559	            ->modalHeading(__('digital-hub::assets.rename_folder'))
560	            ->fillForm(function (array $arguments): array {
561	                $folder = $this->findOwnedFolder($arguments['folder'] ?? null);
562	
563	                return ['name' => $folder?->name];
564	            })
565	            ->schema([
566	                TextInput::make('name')
567	                    ->label(__('digital-hub::assets.folder_name'))
568	                    ->required()
569	                    ->maxLength(255),
570	            ])
571	            ->action(function (array $arguments, array $data): void {
572	                $folder = $this->findOwnedFolder($arguments['folder'] ?? null);
573	                if ($folder === null) {
574	                    return;
575	                }
576	
577	                $folder->name = is_string($data['name']) ? $data['name'] : $folder->name;
578	
579	                if ($this->persistFolder($folder)) {
580	                    Notification::make()->success()->title(__('digital-hub::assets.folder_renamed'))->send();
581	                }
582	            });
583	    }
584	
585	    /**
586	     * Elimina una folder del record. Il model rifiuta la cancellazione se la
587	     * folder contiene sotto-cartelle o media (deleting hook → ValidationException),
588	     * qui intercettata e mostrata come notifica.
589	     */
590	    public function deleteFolderAction(): Action
591	    {
592	        return Action::make('deleteFolder')
593	            ->label(__('digital-hub::assets.delete_folder'))
594	            ->icon(Heroicon::OutlinedTrash)
595	            ->iconButton()
596	            ->color('danger')
597	            ->requiresConfirmation()
598	            ->modalHeading(__('digital-hub::assets.delete_folder_heading'))
599	            ->modalDescription(__('digital-hub::assets.delete_folder_confirmation'))
600	            ->action(function (array $arguments): void {
601	                $folder = $this->findOwnedFolder($arguments['folder'] ?? null);
602	                if ($folder === null) {
603	                    return;
604	                }
605	
606	                // Pre-check dello stesso invariante del deleting hook del model
607	                // (che resta la rete di sicurezza per i path non-UI): rifiuta se
608	                // la folder contiene sotto-cartelle o media.
609	                if ($folder->children()->exists() || $folder->media()->exists()) {
