694	    /**
695	     * Carica uno o più file nella folder attiva (root se nessuna selezionata).
696	     * I file finiscono nella collection asset del record (disco scoped).
697	     */
698	    public function uploadAssetsAction(): Action
699	    {
700	        return Action::make('uploadAssets')
701	            ->label(__('digital-hub::assets.upload'))
702	            ->icon(Heroicon::OutlinedArrowUpTray)
703	            ->modalHeading(__('digital-hub::assets.upload_heading'))
704	            ->schema([
705	                FileUpload::make('files')
706	                    ->label(__('digital-hub::assets.files_field'))
707	                    ->multiple()
708	                    ->required()
709	                    ->storeFiles(false),
710	            ])
711	            ->action(function (array $data): void {
712	                $owner = $this->resolveOwner();
713	                $files = $data['files'] ?? [];
714	                if (! is_array($files)) {
715	                    return;
716	                }
717	
718	                $count = 0;
719	                foreach ($files as $file) {
720	                    if (! $file instanceof TemporaryUploadedFile) {
721	                        continue;
722	                    }
723	
724	                    $media = $owner->addMedia($file)
725	                        ->usingName(pathinfo($file->getClientOriginalName(), PATHINFO_FILENAME))
726	                        ->toMediaCollection($owner->assetsCollection());
727	                    $media->setAttribute('asset_folder_id', $this->activeFolderId);
728	
729	                    // autore: FK nullable verso l'utente + snapshot del nome (fallback
730	                    // se l'utente verrà eliminato → uploaded_by_id null per nullOnDelete)
731	                    /** @disregard P1013 */
732	                    $user = auth()->user();
733	                    $media->setAttribute('uploaded_by_id', $user?->getAuthIdentifier());
734	                    $media->setAttribute('uploaded_by_name', $user instanceof Model ? $user->getAttribute('name') : null);
735	
736	                    // l'elaborazione (metadati, dimensioni, future taglie) la fa un
737	                    // job in coda: il media entra "pending" finché il job non lo chiude
738	                    $media->setAttribute('processing_status', AssetProcessingStatus::Pending->value);
739	                    $media->save();
740	
741	                    $this->dispatchProcessing($media);
742	                    $count++;
743	                }
744	
745	                if ($count > 0) {
746	                    Notification::make()
747	                        ->success()
748	                        ->title(trans_choice('digital-hub::assets.assets_uploaded', $count, ['count' => $count]))
749	                        ->send();
750	                }
751	            });
752	    }
