5	namespace AtrioTeam\DigitalHub\Assets\Support;
6	
7	use Filament\Support\Icons\Heroicon;
8	use Spatie\MediaLibrary\MediaCollections\Models\Media;
9	
10	/**
11	 * Categoria di file di un asset, ai fini della sola presentazione (icona).
12	 *
13	 * Logica di presentazione tenuta fuori dal model Media (di spatie): la mappa
14	 * mime/estensione → categoria → icona vive qui, riusabile da qualunque vista e
15	 * testabile in isolamento. Se in futuro arriverà un model Media custom (#18,
16	 * metadati), potrà esporre `icon()` come one-liner che delega a questo enum.
17	 */
18	enum AssetFileType
19	{
20	    case Image;
21	    case Audio;
22	    case Video;
23	    case Pdf;
24	    case Archive;
25	    case Document;
26	    case Spreadsheet;
27	    case Cad;
28	    case Generic;
29	
30	    /**
31	     * Risolve la categoria da un media (estrae mime + estensione e delega a
32	     * {@see self::fromMime()}). Adapter di comodo: la logica resta in fromMime.
33	     */
34	    public static function fromMedia(Media $media): self
35	    {
36	        $mime = $media->getAttribute('mime_type');
37	        $fileName = $media->getAttribute('file_name');
38	        $extension = is_string($fileName) ? pathinfo($fileName, PATHINFO_EXTENSION) : null;
39	
40	        return self::fromMime(
41	            is_string($mime) ? $mime : null,
42	            $extension,
43	        );
44	    }
45	
46	    /**
47	     * Risolve la categoria dal mime-type, con fallback sull'estensione per i
48	     * tipi il cui mime è inaffidabile o assente (dwg, zip, office…).
49	     */
50	    public static function fromMime(?string $mime, ?string $extension = null): self
51	    {
52	        $mime = strtolower(trim($mime ?? ''));
53	        $ext = strtolower(trim($extension ?? ''));
54	
55	        // Estensione prima: per questi il mime spesso è generico/assente.
56	        $byExtension = match ($ext) {
57	            'dwg', 'dxf' => self::Cad,
58	            'zip', 'rar', '7z', 'tar', 'gz', 'bz2' => self::Archive,
59	            'doc', 'docx', 'odt', 'rtf' => self::Document,
60	            'xls', 'xlsx', 'ods', 'csv' => self::Spreadsheet,
61	            'pdf' => self::Pdf,
62	            default => null,
63	        };
64	        if ($byExtension !== null) {
65	            return $byExtension;
66	        }
67	
68	        return match (true) {
69	            str_starts_with($mime, 'image/') => self::Image,
70	            str_starts_with($mime, 'audio/') => self::Audio,
71	            str_starts_with($mime, 'video/') => self::Video,
72	            $mime === 'application/pdf' => self::Pdf,
73	            in_array($mime, [
74	                'application/zip',
75	                'application/x-zip-compressed',
76	                'application/x-7z-compressed',
77	                'application/x-rar-compressed',
78	                'application/x-rar',
79	                'application/gzip',
80	                'application/x-tar',
81	                'application/x-bzip2',
82	            ], true) => self::Archive,
83	            in_array($mime, [
84	                'application/msword',
85	                'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
86	                'application/vnd.oasis.opendocument.text',
87	                'application/rtf',
88	            ], true) => self::Document,
89	            in_array($mime, [
90	                'application/vnd.ms-excel',
91	                'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
92	                'application/vnd.oasis.opendocument.spreadsheet',
93	                'text/csv',
94	            ], true) => self::Spreadsheet,
95	            in_array($mime, [
96	                'image/vnd.dwg',
97	                'application/acad',
98	                'application/x-acad',
99	                'application/dwg',
100	                'application/x-dwg',
101	                'application/autocad_dwg',
102	                'drawing/dwg',
103	            ], true) => self::Cad,
104	            str_starts_with($mime, 'text/') => self::Document,
105	            default => self::Generic,
106	        };
107	    }
108	
109	    /**
110	     * Comodità: l'asset è un'immagine (anteprima mostrabile, dimensioni estraibili).
111	     * Punto unico per la distinzione "è immagine?" usata da UI e pipeline.
112	     */
113	    public function isImage(): bool
114	    {
115	        return $this === self::Image;
116	    }
117	
118	    public function isVideo(): bool
119	    {
120	        return $this === self::Video;
121	    }
122	
123	    public function isAudio(): bool
124	    {
125	        return $this === self::Audio;
126	    }
127	
128	    public function isPdf(): bool
129	    {
130	        return $this === self::Pdf;
131	    }
132	
133	    /**
134	     * Riproducibile inline con un player (audio/video). NB: indica la categoria,
135	     * non garantisce il supporto codec/contenitore del browser.
136	     */
137	    public function isPlayable(): bool
138	    {
139	        return $this->isVideo() || $this->isAudio();
140	    }
141	
142	    /**
143	     * Ingrandibile (zoom/lightbox) dal pannello info: immagini e video "in grande",
144	     * PDF in un viewer embedded. Gli altri tipi (audio, archivi, documenti, cad,
145	     * generici) non hanno zoom. Punto unico per la distinzione usata dalla UI.
146	     */
147	    public function isZoomable(): bool
148	    {
149	        return $this->isImage() || $this->isVideo() || $this->isPdf();
150	    }
151	
152	    /**
153	     * Icona Heroicon rappresentativa della categoria.
154	     */
155	    public function icon(): Heroicon
156	    {
157	        return match ($this) {
158	            self::Image => Heroicon::OutlinedPhoto,
159	            self::Audio => Heroicon::OutlinedMusicalNote,
160	            self::Video => Heroicon::OutlinedFilm,
161	            self::Pdf => Heroicon::OutlinedDocumentText,
162	            self::Archive => Heroicon::OutlinedArchiveBox,
163	            self::Document => Heroicon::OutlinedDocument,
164	            self::Spreadsheet => Heroicon::OutlinedTableCells,
165	            self::Cad => Heroicon::OutlinedCubeTransparent,
166	            self::Generic => Heroicon::OutlinedPaperClip,
167	        };
168	    }
169	}
