4	
5	namespace AtrioTeam\DigitalHub\Assets\Support;
6	
7	use AtrioTeam\DigitalHub\Assets\Models\AssetFolder;
8	use Illuminate\Database\Eloquent\Collection as EloquentCollection;
9	
10	/**
11	 * Operazioni ad albero sulle folder di un record, senza dipendenze da Livewire.
12	 *
13	 * Avvolge la collection già caricata delle folder ({@see AssetFolder}) e ci
14	 * cammina sopra in memoria: nessuna query. È la fonte unica delle derivate ad
15	 * albero (annidamento, breadcrumb, discendenti, altezza, opzioni di select)
16	 * usate dall'AssetManager, estratta per tenere AssetManager più leggero e rendere questa
17	 * logica testabile in isolamento.
18	 *
19	 * L'ordine dei fratelli è quello della collection passata: chi la costruisce
20	 * decide l'ordinamento (tipicamente `sort`), qui viene solo preservato.
21	 */
22	final class FolderTree
23	{
24	    /**
25	     * @param EloquentCollection<int, AssetFolder> $folders tutte le folder del record
26	     */
27	    private function __construct(private readonly EloquentCollection $folders)
28	    {
29	    }
30	
31	    /**
32	     * @param EloquentCollection<int, AssetFolder> $folders tutte le folder del record
33	     */
34	    public static function fromFolders(EloquentCollection $folders): self
35	    {
36	        return new self($folders);
37	    }
38	
39	    /**
40	     * Fratelli diretti sotto un parent (null = root), nell'ordine della collection.
41	     *
42	     * @return EloquentCollection<int, AssetFolder>
43	     */
44	    public function childrenOf(?int $parentId): EloquentCollection
45	    {
46	        return $this->folders->where('parent_id', $parentId)->values();
47	    }
48	
49	    /**
50	     * Albero annidato a partire da un parent (null = root). `children` è
51	     * ricorsivamente la stessa struttura (non esprimibile come tipo ricorsivo
52	     * preciso in PHPDoc, quindi `mixed`).
53	     *
54	     * @return array<int, array{folder: AssetFolder, children: mixed}>
55	     */
56	    public function nested(?int $parentId = null): array
57	    {
58	        return $this->childrenOf($parentId)
59	            ->map(fn (AssetFolder $folder): array => [
60	                'folder' => $folder,
61	                'children' => $this->nested($folder->id),
62	            ])
63	            ->values()
64	            ->all();
65	    }
66	
67	    /**
68	     * Catena dalla root alla folder data (inclusa), per il breadcrumb. null se la
69	     * folder — o un suo antenato — non è presente nella collection (folder
70	     * eliminata sotto i piedi): il chiamante decide come reagire.
71	     *
72	     * @return list<AssetFolder>|null
73	     */
74	    public function breadcrumb(int $folderId): ?array
75	    {
76	        $trail = [];
77	        $id = $folderId;
78	
79	        while ($id !== null) {
80	            $folder = $this->folders->firstWhere('id', $id);
81	            if (! $folder instanceof AssetFolder) {
82	                return null;
83	            }
84	
85	            array_unshift($trail, $folder);
86	            $id = $folder->parent_id;
87	        }
88	
89	        return $trail;
90	    }
91	
92	    /**
93	     * Id della folder e di tutte le sue discendenti.
94	     *
95	     * @return list<int>
96	     */
97	    public function descendantIds(int $folderId): array
98	    {
99	        $ids = [$folderId];
100	
101	        foreach ($this->folders->where('parent_id', $folderId) as $child) {
102	            $ids = array_merge($ids, $this->descendantIds($child->id));
103	        }
104	
105	        return $ids;
106	    }
107	
108	    /**
109	     * Altezza del sottoalbero di una folder (0 se non ha figli): numero di livelli
110	     * sotto di essa. Serve a validare la profondità risultante quando si sposta
111	     * una folder con discendenti.
112	     */
113	    public function height(int $folderId): int
114	    {
115	        $max = 0;
116	
117	        foreach ($this->folders->where('parent_id', $folderId) as $child) {
118	            $max = max($max, 1 + $this->height($child->id));
119	        }
120	
121	        return $max;
122	    }
123	
124	    /**
125	     * Opzioni per un Select "sposta in", in ordine gerarchico con rientro per
126	     * livello. Se $excludeId è dato, salta quella folder e tutto il suo
127	     * sottoalbero (una folder non può finire dentro sé stessa o un discendente).
128	     *
129	     * @return array<int, string>
130	     */
131	    public function selectOptions(?int $excludeId = null): array
132	    {
133	        $options = [];
134	        $this->appendOptions(null, 0, $options, $excludeId);
135	
136	        return $options;
137	    }
138	
139	    /**
140	     * @param array<int, string> $options
141	     */
142	    private function appendOptions(?int $parentId, int $depth, array &$options, ?int $excludeId): void
143	    {
144	        foreach ($this->folders->where('parent_id', $parentId) as $folder) {
145	            if ($excludeId !== null && $folder->id === $excludeId) {
146	                continue; // salta la folder e (non ricorrendo) il suo sottoalbero
147	            }
148	
149	            $options[$folder->id] = str_repeat('— ', $depth) . $folder->name;
150	            $this->appendOptions($folder->id, $depth + 1, $options, $excludeId);
151	        }
152	    }
153	}
